from collections import deque, Counter

def solve(grid):
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])

    # BFS from all zero cells on the border to find external zeros
    visited = set()
    q = deque()

    # add border zero cells
    for i in range(rows):
        if grid[i][0] == 0:
            q.append((i, 0))
            visited.add((i, 0))
        if grid[i][cols - 1] == 0 and cols - 1 != 0:
            q.append((i, cols - 1))
            visited.add((i, cols - 1))
    for j in range(cols):
        if grid[0][j] == 0:
            q.append((0, j))
            visited.add((0, j))
        if grid[rows - 1][j] == 0 and rows - 1 != 0:
            q.append((rows - 1, j))
            visited.add((rows - 1, j))

    # explore external zero region
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if grid[ni][nj] == 0 and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    q.append((ni, nj))

    # collect interior zero cells (not reachable from border)
    interior = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and (i, j) not in visited:
                interior.append((i, j))

    if not interior:
        # no hole found, return 0 (should not happen for valid inputs)
        return [[0]]

    # find colors of non‑zero cells adjacent to any interior zero
    color_counts = Counter()
    for i, j in interior:
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                val = grid[ni][nj]
                if val != 0:
                    color_counts[val] += 1

    if not color_counts:
        return [[0]]

    # the color forming the hole
    hole_color = color_counts.most_common(1)[0][0]
    return [[hole_color]]

